item.command:
/bin/bash -lc "sleep 2; python - <<'PY'
import urllib.request, urllib.parse, json, time
for id in ['4642','587372']:
 print('\\nID',id)
 for db in ['clinvar']:
  url='https://eutils.ncbi.nlm.nih.gov/entrez/eutils/esummary.fcgi?'+urllib.parse.urlencode({'db':db,'id':id,'retmode':'json'})
  req=urllib.request.Request(url,headers={'User-Agent':'codex-galaxy-variant-lookup/1.0'})
  try:
   data=json.load(urllib.request.urlopen(req, timeout=20))
   print(json.dumps(data['result'][id], indent=2)[:2000])
  except Exception as e: print('err',e)
  time.sleep(1)
PY"

